    def validate_tags(cls, value: list[str]) -> list[str]:
        cleaned: list[str] = []
        seen: set[str] = set()
        for tag in value:
            normalized = str(tag).strip()
            if not normalized:
                continue
            if normalized not in seen:
                seen.add(normalized)
                cleaned.append(normalized)
        return sorted(cleaned)


